"use client"

// Add this function to your CoursePage.jsx file
// This should be added near the top with your other imports
import { useEffect } from "react"
import { useLocation, useNavigate } from "react-router-dom"
import { useDispatch } from "react-redux"
import { useSelector } from "react-redux"
import { verifyPayment } from "../services/operations/paymentAPI"

// Then add this inside your CoursePage component
const CoursePage = () => {
  const location = useLocation()
  const navigate = useNavigate()
  const dispatch = useDispatch()
  const { token } = useSelector((state) => state.auth)

  // Check for payment success on component mount
  useEffect(() => {
    // Check if we're returning from Stripe with a session_id
    const queryParams = new URLSearchParams(location.search)
    const sessionId = queryParams.get("session_id")

    if (sessionId && token) {
      // Verify the payment
      verifyPayment(sessionId, token, navigate, dispatch)

      // Clean up the URL
      const newUrl = window.location.pathname
      window.history.replaceState({}, document.title, newUrl)
    }
  }, [location, token, navigate, dispatch])

  return (
    <div>
      {/* Course Page Content */}
      <h1>Course Page</h1>
      <p>This is the course page content.</p>
    </div>
  )
}

export default CoursePage
